/** Permission to wear required gear; ownership is not inferred. */
export interface DiaryEquipmentRequirement {
  slot: EquipmentSlot;
  tier: number;
  reason: string;
  /** Unreviewed item tiers require a player check, never a guessed hard gate. */
  manualCheck?: string;
  /** A completed diary reward removes this equipment requirement. */
  unlessDiary?: string;
}

export interface DiaryLocationRequirement {
  label: string;
  chunkOptions: Array<{ cx: number; cy: number }>;
}

export interface DiaryTaskRequirementOption {
  label?: string;
  skills?: Record<string, number>;
  items?: string[];
  merchants?: string[];
  mobility?: string[];
  arcana?: string[];
  minigames?: string[];
  equipmentRequirements?: DiaryEquipmentRequirement[];
  quests?: string[];
  cas?: string[];
  regions?: string[];
  locations?: DiaryLocationRequirement[];
  questPoints?: number;
  manualRequirements?: string[];
  questProgress?: QuestProgressRequirement[];
  combatLevel?: number;
  allQuests?: true;
  anySkillLevel?: number;
  combinedSkillLevel?: { skills: string[]; level: number };
  anyOfSkillsLevel?: { skills: string[]; level: number };
}

export interface DiaryTask {
  id: string;
  tierId: string;
  description: string;
  skills?: Record<string, number>;
  items?: string[];
  merchants?: string[];
  mobility?: string[];
  arcana?: string[];
  minigames?: string[];
  equipmentRequirements?: DiaryEquipmentRequirement[];
  quests?: string[];
  cas?: string[];
  regions?: string[];
  locations?: DiaryLocationRequirement[];
  anyOfRegions?: string[];
  questPoints?: number;
  manualRequirements?: string[];
  questProgress?: QuestProgressRequirement[];
  combatLevel?: number;
  allQuests?: true;
  anySkillLevel?: number;
  combinedSkillLevel?: { skills: string[]; level: number };
  anyOfSkillsLevel?: { skills: string[]; level: number };
  oneOf?: DiaryTaskRequirementOption[];
}

